-- Starting content for the redo: pages, menus, social links, praise,
-- consent wording and email templates. Generated by
-- scripts/content/build-seed.ts; edit that script, not this file.
--
-- Everything here only fills what is missing. Re-running it, or running it on
-- the live database, never overwrites an edit made in the studio.

-- Site settings: fill blanks only.
update public.site_settings set
  site_name = coalesce(nullif(site_name, ''), 'Anastasia Patience'),
  tagline = coalesce(nullif(tagline, ''), 'Find your reason to smile.'),
  default_seo_title = coalesce(nullif(default_seo_title, ''), 'Anastasia Patience'),
  default_seo_description = coalesce(nullif(default_seo_description, ''), 'Author, storyteller and founder of Patience Media House. Books, an audiobook in her own voice, and letters on faith, loss and building a life you love.'),
  footer_text = coalesce(nullif(footer_text, ''), 'Author, storyteller, entrepreneur. Founder of Patience Media House.'),
  social_image_id = coalesce(social_image_id, (select id from public.media_assets where id = '5eed0000-0000-4000-8000-000000000015'::uuid))
where id = 'site';

-- Pages.
insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/', 'home', true, 'Home', 'Anastasia Patience: Find Your Reason to Smile', 'Author, storyteller and founder of Patience Media House. Books, an audiobook in her own voice, and letters on faith, loss and building a life you love.', 'published', now(), replace('[{"id":"c0de0001-0000-4000-8000-000000000001","type":"hero","variant":"portrait_arch","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"title":"Turning pain into purpose.","accent":"purpose.","body":"I’m Anastasia. I help women turn their scars into stories, their stories into skills, and their skills into a life they love.","imageMediaId":"5eed0000-0000-4000-8000-000000000001","caption":"A daughter of Ghana, a woman of Cyprus, a mother by miracle, and a storyteller by calling.","primary":{"label":"Read my story","href":"/about"},"secondary":{"label":"","href":""},"listenCta":true,"facts":[]}},{"id":"c0de0002-0000-4000-8000-000000000002","type":"audiobook_player","variant":"shelf","settings":{"hidden":false,"anchor":"listen","width":"default","spacing":"default","background":"cream"},"props":{"title":"Listen, in my own voice.","intro":"","audiobookIds":[]}},{"id":"c0de0003-0000-4000-8000-000000000003","type":"featured_book","variant":"cover_left","settings":{"hidden":false,"anchor":"book","width":"default","spacing":"default","background":"ivory"},"props":{"bookId":"b00c0000-0000-4000-8000-000000000001","quote":"I read this in one sitting and cried the good kind of tears. It felt like a long letter from a wise older sister.","quoteBy":"Ama, Accra","showEbookGate":true}},{"id":"c0de0004-0000-4000-8000-000000000004","type":"quote","variant":"centred","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"quote":"No matter what you’re facing, your reason to smile still exists.","source":"Find Your Reason to Smile","attribution":""}},{"id":"c0de0005-0000-4000-8000-000000000005","type":"video","variant":"filmstrip","settings":{"hidden":false,"anchor":"videos","width":"default","spacing":"default","background":"cocoa"},"props":{"title":"On stage, on camera.","videoIds":[],"channelLink":{"label":"","href":""}}},{"id":"c0de0006-0000-4000-8000-000000000006","type":"two_column","variant":"image_left","settings":{"hidden":false,"anchor":"foundation","width":"default","spacing":"default","background":"cream"},"props":{"title":"Where no one feels left behind.","lead":"We support individuals, families, and vulnerable lives facing hardship — through food assistance, compassionate care, community outreach, and care for rescued animals.","body":"<p>Each case is a person — not a number. Stories shared with care and permission.</p>","imageMediaId":"5eed0000-0000-4000-8000-000000000010","caption":"Feeding hope, one heart at a time.","primary":{"label":"Donate","href":"/foundation#give"},"link":{"label":"Volunteer","href":"/contact"},"secondary":{"label":"Impact stories","href":"/foundation#stories"}}},{"id":"c0de0007-0000-4000-8000-000000000007","type":"latest_posts","variant":"list","settings":{"hidden":false,"anchor":"stories","width":"default","spacing":"default","background":"ivory"},"props":{"title":"Stories from the honest middle.","categoryId":null,"count":3,"showCategories":true,"paginate":false,"link":{"label":"All stories","href":"/blog"}}}]', 'b00c0000-0000-4000-8000-000000000001', coalesce((select id::text from public.books where slug = 'find-your-reason-to-smile'), 'b00c0000-0000-4000-8000-000000000001'))::jsonb)
on conflict (path) do nothing;

insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/about', 'standard', false, 'About', 'About Anastasia Patience', 'From Ghana to Cyprus, through loss, faith and motherhood: how Anastasia became an author, a storyteller and the founder of Patience Media House.', 'published', now(), '[{"id":"c0de0011-0000-4000-8000-000000000011","type":"hero","variant":"portrait_right","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"title":"A life rewritten in the margins.","accent":"","body":"My name is Anastasia Patience. I am a daughter of Ghana, a woman of Cyprus, a mother by miracle, and a storyteller by calling. This is the long version.","imageMediaId":"5eed0000-0000-4000-8000-000000000002","caption":"","primary":{"label":"","href":""},"secondary":{"label":"","href":""},"listenCta":false,"facts":[{"id":"c0de0008-0000-4000-8000-000000000008","label":"Based in","value":"Cyprus"},{"id":"c0de0009-0000-4000-8000-000000000009","label":"Continents that raised me","value":"Africa & Europe"},{"id":"c0de0010-0000-4000-8000-000000000010","label":"Founder of","value":"Patience Media House"}]}},{"id":"c0de0012-0000-4000-8000-000000000012","type":"rich_text","variant":"foreword","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"cream"},"props":{"title":"Every scar is a syllabus.","body":"<p>My story is stitched together from grief, faith, and stubborn hope — and every book, masterclass, and blog post I make is a hand extended back to you.</p><p>Every mother is a mystic. Every ordinary woman carries something the world desperately needs — usually the exact thing she thinks disqualifies her.</p><p>I write for the woman rebuilding after loss, the mother whispering prayers over a sick child, the entrepreneur with a dream she’s afraid to name.</p>"}},{"id":"c0de0022-0000-4000-8000-000000000022","type":"timeline","variant":"vertical","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"title":"Every season taught me something.","items":[{"id":"c0de0013-0000-4000-8000-000000000013","label":"The beginning","title":"My parents","body":"My mother taught me to pray — and to stay quiet and steady in difficult times. My father taught me to work hard with discipline: to be polite, honest, and respectful.","imageMediaId":null,"caption":"","pullQuote":""},{"id":"c0de0014-0000-4000-8000-000000000014","label":"The crossing","title":"Two suitcases","body":"At twenty-four, I boarded a plane with two suitcases and a promise. I would build a life. I would send money home. I would become someone.","imageMediaId":"5eed0000-0000-4000-8000-000000000009","caption":"From Ghana to Cyprus — and everywhere in between.","pullQuote":""},{"id":"c0de0015-0000-4000-8000-000000000015","label":"The work","title":"Caregiver","body":"For years I cared for the elderly. Their stories became mine. Their loneliness taught me presence. Their courage taught me endurance.","imageMediaId":null,"caption":"","pullQuote":""},{"id":"c0de0016-0000-4000-8000-000000000016","label":"The first loss","title":"My brother","body":"When my younger brother died, something inside me broke that I didn’t know could break. I learned that grief has weather. Some days it rains and rains and doesn’t stop.","imageMediaId":null,"caption":"","pullQuote":""},{"id":"c0de0017-0000-4000-8000-000000000017","label":"The unmooring","title":"Without parents","body":"Losing my mother years later left me unmoored. Without parents in a foreign country, I had to find my own way — and become my own compass.","imageMediaId":null,"caption":"","pullQuote":""},{"id":"c0de0018-0000-4000-8000-000000000018","label":"The choice","title":"The pregnancy","body":"The doctors said terminate. There were risks. There were reasons. There were papers to sign. His name would become my miracle — because I believed his life was worth fighting for, even when the world told me otherwise.","imageMediaId":null,"caption":"","pullQuote":"I chose faith. I chose him."},{"id":"c0de0019-0000-4000-8000-000000000019","label":"The miracle","title":"My son","body":"He came into this world small, quiet, and perfect — already carrying a strength I could see in him. He is the reason I know God still writes stories with impossible endings.","imageMediaId":"5eed0000-0000-4000-8000-000000000010","caption":"","pullQuote":""},{"id":"c0de0020-0000-4000-8000-000000000020","label":"The dark room","title":"Depression","body":"Postpartum depression came like a fog with no exit. I stopped smiling. I stopped writing. I stopped believing I was still in there. Slowly, gently, I found my way back.","imageMediaId":null,"caption":"","pullQuote":""},{"id":"c0de0021-0000-4000-8000-000000000021","label":"Now","title":"Author & founder","body":"I write the books I needed. I teach the classes I wished I had. Find Your Reason to Smile is my letter to every woman who ever felt too broken to begin again.","imageMediaId":null,"caption":"","pullQuote":""}],"link":{"label":"Read the book","href":"/books/find-your-reason-to-smile"}}},{"id":"c0de0023-0000-4000-8000-000000000023","type":"quote","variant":"statement","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"quote":"To hand every woman a lantern for the dark seasons, and a map to build a life she loves once the light returns.","source":"","attribution":"My mission"}},{"id":"c0de0029-0000-4000-8000-000000000029","type":"list","variant":"plain","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"cream"},"props":{"title":"Five values, one calling.","intro":"","items":[{"id":"c0de0024-0000-4000-8000-000000000024","title":"Faith","body":"Faith is the muscle I train first, every morning."},{"id":"c0de0025-0000-4000-8000-000000000025","title":"Resilience","body":"Not the loud kind. The quiet, unglamorous, keep-going kind."},{"id":"c0de0026-0000-4000-8000-000000000026","title":"Purpose","body":"I teach what I’ve lived."},{"id":"c0de0027-0000-4000-8000-000000000027","title":"Story","body":"Stories heal what statistics can’t reach."},{"id":"c0de0028-0000-4000-8000-000000000028","title":"Service","body":"If it doesn’t help someone rise, I don’t build it."}]}},{"id":"c0de0030-0000-4000-8000-000000000030","type":"call_to_action","variant":"band","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"title":"Start with chapter one.","body":"","link":{"label":"Listen to the first chapter","href":"/#listen"},"secondary":{"label":"Get the free eBook","href":"/#free-ebook"}}}]'::jsonb)
on conflict (path) do nothing;

