values ('/foundation', 'standard', false, 'Patience Humanitarian Foundation', 'Patience Humanitarian Foundation', 'Where no one feels left behind: food assistance, compassionate care, community support and care for rescued animals.', 'published', now(), '[{"id":"c0de0036-0000-4000-8000-000000000036","type":"hero","variant":"photo","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"title":"Where no one feels left behind.","accent":"","body":"We support individuals, families, and vulnerable lives facing hardship — through food assistance, compassionate care, community outreach, and care for rescued animals.","imageMediaId":"5eed0000-0000-4000-8000-000000000010","caption":"","primary":{"label":"Donate","href":"#give"},"secondary":{"label":"Impact stories","href":"#stories"},"listenCta":false,"facts":[]}},{"id":"c0de0041-0000-4000-8000-000000000041","type":"list","variant":"plain","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"title":"Four ways we care.","intro":"","items":[{"id":"c0de0037-0000-4000-8000-000000000037","title":"Food assistance","body":"Groceries and warm meals for families who are going without."},{"id":"c0de0038-0000-4000-8000-000000000038","title":"Compassionate care","body":"Visits, company and practical help for the elderly, the sick and the lonely."},{"id":"c0de0039-0000-4000-8000-000000000039","title":"Community support","body":"Standing with families through hard seasons, so no one faces them alone."},{"id":"c0de0040-0000-4000-8000-000000000040","title":"Rescued animals","body":"Food, shelter and veterinary care for animals that have been abandoned."}]}},{"id":"c0de0042-0000-4000-8000-000000000042","type":"donation","variant":"card","settings":{"hidden":false,"anchor":"give","width":"default","spacing":"default","background":"cream"},"props":{"title":"Together, we can make a difference.","body":"Every gift becomes a meal, a visit or a rescue. Give once, or walk with us every month.","amounts":[10,25,50,100],"allowMonthly":true}},{"id":"c0de0043-0000-4000-8000-000000000043","type":"foundation_stories","variant":"grid","settings":{"hidden":false,"anchor":"stories","width":"default","spacing":"default","background":"ivory"},"props":{"title":"Faces we hold close.","categoryId":null,"count":6}},{"id":"c0de0049-0000-4000-8000-000000000049","type":"list","variant":"plain","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"cream"},"props":{"title":"What guides every act of care.","intro":"","items":[{"id":"c0de0044-0000-4000-8000-000000000044","title":"Compassion","body":"We meet people where they are."},{"id":"c0de0045-0000-4000-8000-000000000045","title":"Dignity","body":"Help is given with respect, and stories are shared only with permission."},{"id":"c0de0046-0000-4000-8000-000000000046","title":"Service","body":"We show up, quietly and consistently."},{"id":"c0de0047-0000-4000-8000-000000000047","title":"Hope","body":"Every meal and every visit says: you are not forgotten."},{"id":"c0de0048-0000-4000-8000-000000000048","title":"Community","body":"None of this happens alone."}]}}]'::jsonb)
on conflict (path) do nothing;

