insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/start', 'links', true, 'Anastasia Patience', 'Start here: Anastasia Patience', 'Everything in one place: the free ebook, the audiobook, my stories, masterclasses and the foundation.', 'published', now(), (
    with old as (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', l.id, 'label', left(l.label, 80), 'description', left(coalesce(l.sub, ''), 140),
        'href', coalesce(l.to_path, l.href), 'featured', false
      ) order by l.sort_order), '[]'::jsonb) as items
      from public.start_page_links l
      where l.enabled
        and (l.to_path ~ '^/[a-z0-9/-]*$' or l.href ~ '^https://')
        and coalesce(l.to_path, l.href) not in ('/books#free-ebook', '/#listen', '/blog', '/masterclasses', '/foundation', '/books', '/masterclasses', '/blog', '/foundation')
    )
    select jsonb_set(s.v, '{0,props,items}', (s.v #> '{0,props,items}') || old.items)
    from old, (select '[{"id":"c0de0066-0000-4000-8000-000000000066","type":"link_list","variant":"stacked","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"items":[{"id":"c0de0061-0000-4000-8000-000000000061","label":"Get the free ebook","description":"Find Your Reason to Smile, free to download","href":"/books#free-ebook","featured":true},{"id":"c0de0062-0000-4000-8000-000000000062","label":"Listen to the audiobook","description":"The first chapters, in my own voice","href":"/#listen","featured":false},{"id":"c0de0063-0000-4000-8000-000000000063","label":"Read my stories","description":"Stories from the honest middle.","href":"/blog","featured":false},{"id":"c0de0064-0000-4000-8000-000000000064","label":"Masterclasses","description":"Turn what you know into income","href":"/masterclasses","featured":false},{"id":"c0de0065-0000-4000-8000-000000000065","label":"Patience Humanitarian Foundation","description":"Where no one feels left behind","href":"/foundation","featured":false}],"showSocialLinks":true}}]'::jsonb as v) s
  ))
on conflict (path) do nothing;

insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/privacy', 'legal', true, 'Privacy', 'Privacy notice', 'What this website collects, why, who helps us run it, how long we keep it and your rights.', 'published', now(), '[{"id":"c0de0058-0000-4000-8000-000000000058","type":"rich_text","variant":"one_column","settings":{"hidden":false,"anchor":"","width":"narrow","spacing":"default","background":"ivory"},"props":{"title":"","body":"<p>This website is run by Anastasia Patience and Patience Media House, based in Cyprus. This notice explains what we collect when you use it, why, and what you can ask us to do. To reach us about your data, use the <a href=\"/contact\">contact page</a>.</p><h2>What we collect</h2><ul><li><strong>Letters (newsletter):</strong> your email address and language. You confirm by email before we send anything (double opt-in).</li><li><strong>Free ebook:</strong> your first name, email and language, so we can send the download link. Ticking the letters box is separate and optional.</li><li><strong>Contact form:</strong> your name, email and message.</li><li><strong>Purchases and gifts:</strong> your name, email and, for printed books, your delivery address. Card details go straight to Stripe; we never see them.</li><li><strong>In your browser only:</strong> for the audiobook player, the edition you chose, where you stopped in each chapter, the chapters you have finished and your playback speed; your language choice; and whether you closed the language suggestion. These stay on your device, and we never collect them. More in <a href=\"/cookies\">cookies and storage</a>.</li></ul><h2>Why</h2><p>We use your details only to do what you asked: send the letters you confirmed, the ebook you requested, a reply to your message, or the order you paid for. We rely on your consent for the letters and on taking the steps you asked for everything else. Records of payments are kept because the law requires it.</p><h2>Who helps us run the site</h2><ul><li><strong>Supabase</strong> (database and file storage, in the EU)</li><li><strong>Cloudflare</strong> (hosting, and a check that forms are filled in by people)</li><li><strong>Stripe</strong> (payments)</li><li><strong>Resend</strong> (sending emails)</li><li><strong>Google</strong> (YouTube videos, which load only when you press play)</li></ul><p>We do not sell your data, and we do not use advertising or tracking cookies.</p><h2>How long we keep it</h2><ul><li>Unconfirmed newsletter sign-ups: deleted after 30 days.</li><li>Free ebook requests: 24 months, unless you also confirmed the letters.</li><li>Download links: they stop working after 7 days.</li><li>Contact messages: 24 months after we archive them.</li><li>Email delivery records: 12 months.</li><li>Orders and gifts: for as long as accounting law requires, after which names, emails and addresses are removed.</li></ul><h2>Your rights</h2><p>You can ask to see, correct or delete your data, or object to how we use it. Every letter has an unsubscribe link. If you are unhappy with how we handled your data, you can complain to the Commissioner for Personal Data Protection in Cyprus.</p>"}}]'::jsonb)
on conflict (path) do nothing;

insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/terms', 'legal', true, 'Terms', 'Terms of use', 'The terms for using this website, buying from it and giving through it.', 'published', now(), '[{"id":"c0de0059-0000-4000-8000-000000000059","type":"rich_text","variant":"one_column","settings":{"hidden":false,"anchor":"","width":"narrow","spacing":"default","background":"ivory"},"props":{"title":"","body":"<p>By using this website you agree to these terms. If anything is unclear, please <a href=\"/contact\">get in touch</a>.</p><h2>Words and pictures</h2><p>The writing, recordings and photographs on this site belong to Anastasia Patience unless credited otherwise. You are welcome to share links and short quotations with credit. Please ask before reusing anything else.</p><h2>Digital purchases</h2><p>Ebooks, audio and other digital products are delivered as soon as payment is confirmed, through a download link that works for 7 days. When you buy, you agree that delivery starts straight away, which means the usual 14-day right to cancel ends once the download begins. If a file does not work, tell us and we will fix it or refund you.</p><h2>Printed books</h2><p>Printed books bought through other shops are covered by that shop’s terms.</p><h2>Gifts to the foundation</h2><p>Gifts are used for the foundation’s work. If you gave by mistake, contact us within 30 days and we will refund you. Monthly gifts can be changed or cancelled at any time from the link in your receipt.</p><h2>Masterclasses</h2><p>Each masterclass page sets out what is included, the dates and how to cancel.</p><h2>The law</h2><p>These terms are governed by the laws of the Republic of Cyprus. Nothing here limits your rights as a consumer.</p>"}}]'::jsonb)
on conflict (path) do nothing;

insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/cookies', 'legal', true, 'Cookies', 'Cookies and storage', 'What this website keeps in your browser, and why. No advertising or tracking cookies.', 'published', now(), '[{"id":"c0de0060-0000-4000-8000-000000000060","type":"rich_text","variant":"one_column","settings":{"hidden":false,"anchor":"","width":"narrow","spacing":"default","background":"ivory"},"props":{"title":"","body":"<p>This website uses no advertising or tracking cookies and no analytics. What it keeps in your browser is there to remember your choices. It stays on your device, and we never collect it.</p><h2>What your browser keeps</h2><ul><li><strong>Your language:</strong> when you switch between English and Greek, one cookie (aph_locale) remembers your choice for a year.</li><li><strong>The audiobook player:</strong> for each audiobook edition, the chapter you are on, where you stopped, the chapters you have finished and your playback speed, and the edition you chose in each language. This is kept in your browser’s local storage, so you can pick up where you left off.</li><li><strong>The language suggestion:</strong> if you close the note that offers a page in your browser’s language, local storage remembers it for a year, so the note does not come back.</li><li><strong>The studio:</strong> only Anastasia and her team sign in. Their sign-in is kept in local storage until they sign out.</li></ul><h2>Services that help run the site</h2><ul><li><strong>Cloudflare Turnstile</strong> checks that a form is sent by a person, not a program. Cloudflare says Turnstile uses no cookies.</li><li><strong>YouTube</strong> videos use YouTube’s privacy-enhanced mode and load only when you press play. From then on, YouTube’s own cookies and terms apply to that video.</li><li><strong>Stripe</strong> takes payments on its own checkout pages, which set their own cookies to prevent fraud.</li></ul><h2>Clearing it</h2><p>You can delete all of this at any time in your browser’s settings for this site. Nothing breaks: the player starts again from the first chapter, and the language note may come back.</p><p>For the details you give us in forms and orders, see the <a href=\"/privacy\">privacy notice</a>.</p>"}}]'::jsonb)
on conflict (path) do nothing;

-- Menus, only when there are none yet.
do $$
declare
  _parent uuid;
begin
  if exists (select 1 from public.navigation_items) then
    return;
  end if;

  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'About', (select id from public.pages where path = '/about'), null, null, 0);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Books', (select id from public.pages where path = '/books'), null, null, 1);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Stories', (select id from public.pages where path = '/blog'), null, null, 2);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Videos', (select id from public.pages where path = '/videos'), null, null, 3);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Gallery', (select id from public.pages where path = '/gallery'), null, null, 4);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Foundation', (select id from public.pages where path = '/foundation'), null, null, 5);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Contact', (select id from public.pages where path = '/contact'), null, null, 6);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header_action', 'Free eBook', null, '/#free-ebook', null, 7);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('footer', 'Explore', null, '/', null, 8)
  returning id into _parent;
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position) values
    ('footer', 'About', (select id from public.pages where path = '/about'), null, _parent, 0),
    ('footer', 'Books', (select id from public.pages where path = '/books'), null, _parent, 1),
    ('footer', 'Stories', (select id from public.pages where path = '/blog'), null, _parent, 2),
    ('footer', 'Videos', (select id from public.pages where path = '/videos'), null, _parent, 3),
    ('footer', 'Gallery', (select id from public.pages where path = '/gallery'), null, _parent, 4);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('footer', 'Company', null, '/foundation', null, 9)
  returning id into _parent;
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position) values
    ('footer', 'Foundation', (select id from public.pages where path = '/foundation'), null, _parent, 0),
    ('footer', 'Patience Media House', (select id from public.pages where path = '/shop'), null, _parent, 1),
    ('footer', 'Masterclasses', (select id from public.pages where path = '/masterclasses'), null, _parent, 2),
    ('footer', 'Contact', (select id from public.pages where path = '/contact'), null, _parent, 3);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('legal', 'Privacy', (select id from public.pages where path = '/privacy'), null, null, 10);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('legal', 'Terms', (select id from public.pages where path = '/terms'), null, null, 11);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('legal', 'Cookies', (select id from public.pages where path = '/cookies'), null, null, 12);
end;
$$;

-- Social links from the old start page, when there are none yet.
insert into public.social_links (platform, url, label, position)
select p.platform, s.url, '', s.sort_order
from public.start_page_socials s
cross join lateral (
  select case lower(s.platform)
    when 'twitter' then 'x'
    when 'x' then 'x'
    else lower(s.platform)
  end as platform
) p
where s.enabled
  and s.url ~ '^https://'
  and p.platform in ('instagram', 'facebook', 'youtube', 'tiktok', 'x', 'linkedin', 'threads', 'spotify')
  and not exists (select 1 from public.social_links);

-- The memoir's subtitle, as printed on its cover, when none is set yet.
update public.books
set subtitle = 'A Journey of Faith, Loss, Resilience, and Hope'
where slug = 'find-your-reason-to-smile' and coalesce(subtitle, '') = '';

-- The home lead story, when nothing is featured yet.
update public.blog_posts set featured = true
where slug = 'faith-when-the-doctors-say-no'
  and not exists (select 1 from public.blog_posts where featured);

-- The three starter stories in sentence case, while their titles are still the starter ones.
update public.blog_posts as p
set title = v.title
from (values
  ('the-morning-i-decided-to-keep-going', 'The Morning I Decided To Keep Going', 'The morning I decided to keep going'),
  ('your-first-digital-product-in-30-days', 'Your First Digital Product In 30 Days', 'Your first digital product in 30 days'),
  ('faith-when-the-doctors-say-no', 'Faith, When The Doctors Say No', 'Faith, when the doctors say no')
) as v(slug, seeded, title)
where p.slug = v.slug and p.title = v.seeded;

-- Praise: the reader reviews already on the live site, when there is none yet.
insert into public.testimonials (quote, name, role, book_id, published, position)
select r.quote,
  btrim(split_part(r.by_name, ',', 1)),
  btrim(substr(r.by_name, length(split_part(r.by_name, ',', 1)) + 2)),
  r.book_id, r.published, r.sort_order
from public.book_reviews r
where r.published and not exists (select 1 from public.testimonials);

-- Consent wording, version 1.
insert into public.consent_texts (key, version, body) values
  ('newsletter', 1, 'Send me Anastasia’s letters by email. I can unsubscribe at any time with the link in every letter.'),
  ('ebook_gate', 1, 'We use your first name and email to send you the ebook. We keep them for 24 months, or longer if you also join the letters.'),
  ('contact', 1, 'We use your name, email and message only to reply to you.'),
  ('checkout', 1, 'Your order details are used to deliver what you bought and kept as the law requires for accounting.'),
  ('donation', 1, 'Your details are used to process your gift and send your receipt, and kept as the law requires for accounting.')
on conflict (key, version) do nothing;

